//! `autorename-pdf integrate install|remove|status`: per-user desktop and
//! file-manager integration (spec §OS integration & packaging).
//!
//! Every entry is generated by a pure function (golden-tested on any OS) and
//! carries an ownership marker; `remove` deletes only entries that carry it
//! (Thunar: only our `<action>` blocks), so user files are never touched.
//! `install` is idempotent: identical entries are left alone, outdated owned
//! entries are rewritten, foreign files with our names are reported, not
//! overwritten.
//!
//! - Linux: `.desktop` app entry (MIME + actions), hicolor icons, Dolphin
//!   service menu, Nemo actions, Thunar `uca.xml` merge, Nautilus scripts.
//!   File-manager entries are installed only for hosts found on this system;
//!   `remove` always checks every location.
//! - Windows: HKCU classic context menu (`windows.rs`).
//! - macOS: Finder Quick Actions in `~/Library/Services` (`macos.rs`).

// The file engine serves Linux and macOS; Windows uses the registry.
#![cfg_attr(windows, allow(dead_code))]

pub mod linux;
pub mod macos;
pub mod windows;

use std::path::{Path, PathBuf};

use serde::Serialize;

/// Marker line/key present in every generated text entry.
pub const MARKER: &str = "X-AutoRename-PDF-Integration";
/// Icon theme name (hicolor) and desktop-file id.
pub const APP_ID: &str = "autorename-pdf";
pub const PRODUCT: &str = "AutoRename-PDF";

/// The two verbs every host gets.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Verb {
    /// `gui --rename-now <paths>`: plan + apply in a small window.
    RenameNow,
    /// `gui <paths>`: open the preview.
    Preview,
}

impl Verb {
    pub const ALL: [Verb; 2] = [Verb::RenameNow, Verb::Preview];

    pub fn id(self) -> &'static str {
        match self {
            Verb::RenameNow => "rename-now",
            Verb::Preview => "preview",
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            Verb::RenameNow => "Rename now",
            Verb::Preview => "Preview in AutoRename-PDF",
        }
    }

    /// Arguments after the executable (before the selected paths).
    pub fn args(self) -> &'static [&'static str] {
        match self {
            Verb::RenameNow => &["gui", "--rename-now"],
            Verb::Preview => &["gui"],
        }
    }
}

/// One generated file.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FileEntry {
    pub kind: &'static str,
    pub path: PathBuf,
    pub bytes: Vec<u8>,
    pub executable: bool,
    /// Owned by name (icons: binary, no marker), else by [`MARKER`].
    pub owned_by_name: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, schemars::JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum State {
    /// Present and identical to what `install` writes.
    Installed,
    /// Ours, but differs (older version or another executable path).
    Outdated,
    /// Not present.
    Missing,
    /// A file with our name that is not ours: never touched.
    Foreign,
    /// Host (file manager) not found: not installed.
    Skipped,
}

#[derive(Debug, Clone, Serialize, schemars::JsonSchema)]
pub struct Item {
    pub kind: String,
    pub path: String,
    pub state: State,
    /// What the last `install`/`remove` did: written, unchanged, removed, kept.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub action: Option<&'static str>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub note: Option<String>,
}

#[derive(Debug, Clone, Serialize, schemars::JsonSchema)]
pub struct Report {
    pub platform: &'static str,
    pub scope: &'static str,
    /// Command the entries launch.
    pub command: String,
    pub items: Vec<Item>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub notes: Vec<String>,
}

pub fn has_marker(bytes: &[u8]) -> bool {
    String::from_utf8_lossy(bytes).contains(MARKER)
}

pub fn sha256_hex(bytes: &[u8]) -> String {
    use sha2::{Digest, Sha256};
    Sha256::digest(bytes)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

/// Read an existing entry: `Ok(None)` only when it does not exist.
fn read_existing(path: &Path) -> std::io::Result<Option<Vec<u8>>> {
    match std::fs::read(path) {
        Ok(b) => Ok(Some(b)),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            // A dangling symlink is still somebody's file.
            if std::fs::symlink_metadata(path).is_ok() {
                Err(e)
            } else {
                Ok(None)
            }
        }
        Err(e) => Err(e),
    }
}

/// Ownership: text entries by [`MARKER`]; by-name entries (icons) only when
/// the log recorded that we wrote exactly the bytes that are there now.
fn state_of(e: &FileEntry, log: &OwnedLog) -> State {
    match read_existing(&e.path) {
        Ok(None) => State::Missing,
        Ok(Some(b)) if b == e.bytes => State::Installed,
        Ok(Some(b)) if e.owned_by_name && log.owns_file(&e.path, &b) => State::Outdated,
        Ok(Some(b)) if !e.owned_by_name && has_marker(&b) => State::Outdated,
        // Foreign content, or unreadable: never touched.
        Ok(Some(_)) | Err(_) => State::Foreign,
    }
}

/// Is the file at `e.path` ours to delete?
fn removable(e: &FileEntry, log: &OwnedLog) -> bool {
    match read_existing(&e.path) {
        Ok(Some(b)) if e.owned_by_name => log.owns_file(&e.path, &b),
        Ok(Some(b)) => has_marker(&b),
        _ => false,
    }
}

fn item(e: &FileEntry, state: State, action: Option<&'static str>) -> Item {
    Item {
        kind: e.kind.into(),
        path: e.path.display().to_string(),
        state,
        action,
        note: None,
    }
}

pub fn status_files(entries: &[FileEntry], log: &OwnedLog) -> Vec<Item> {
    entries
        .iter()
        .map(|e| item(e, state_of(e, log), None))
        .collect()
}

#[cfg(unix)]
fn set_mode(path: &Path, executable: bool) -> std::io::Result<()> {
    use std::os::unix::fs::PermissionsExt;
    let mode = if executable { 0o755 } else { 0o644 };
    std::fs::set_permissions(path, std::fs::Permissions::from_mode(mode))
}

#[cfg(not(unix))]
fn set_mode(_: &Path, _: bool) -> std::io::Result<()> {
    Ok(())
}

/// What `install` created, persisted so `remove` deletes exactly that:
/// directories that did not exist (never a pre-existing, possibly empty user
/// directory such as `nautilus/scripts`) and by-name files with the SHA-256
/// we wrote (a foreign or later modified icon is never overwritten/deleted).
///
/// Format: `D <path>` and `F <sha256> <path>` lines.
#[derive(Debug)]
pub struct OwnedLog {
    file: PathBuf,
    dirs: std::collections::BTreeSet<PathBuf>,
    files: std::collections::BTreeMap<PathBuf, String>,
    /// Symlinks we created → their target (`L <link>\t<target>`).
    pub links: std::collections::BTreeMap<PathBuf, PathBuf>,
}

impl OwnedLog {
    pub fn load(file: PathBuf) -> OwnedLog {
        let mut log = OwnedLog {
            file,
            dirs: Default::default(),
            files: Default::default(),
            links: Default::default(),
        };
        if let Ok(s) = std::fs::read_to_string(&log.file) {
            for l in s.lines() {
                if let Some(d) = l.strip_prefix("D ") {
                    log.dirs.insert(d.into());
                } else if let Some((link, target)) =
                    l.strip_prefix("L ").and_then(|r| r.split_once('\t'))
                {
                    log.links.insert(link.into(), target.into());
                } else if let Some((h, p)) = l.strip_prefix("F ").and_then(|r| r.split_once(' ')) {
                    log.files.insert(p.into(), h.to_string());
                }
            }
        }
        log
    }

    pub fn owns_file(&self, path: &Path, bytes: &[u8]) -> bool {
        self.files
            .get(path)
            .is_some_and(|h| *h == sha256_hex(bytes))
    }

    /// `create_dir_all`, recording every directory that did not exist.
    pub fn create_dir_all(&mut self, dir: &Path) -> std::io::Result<()> {
        let mut missing = Vec::new();
        let mut d = Some(dir);
        while let Some(p) = d {
            if std::fs::symlink_metadata(p).is_ok() {
                break;
            }
            missing.push(p.to_path_buf());
            d = p.parent();
        }
        std::fs::create_dir_all(dir)?;
        self.dirs
            .extend(missing.into_iter().filter(|p| p.to_str().is_some()));
        Ok(())
    }

    pub fn save(&mut self) -> std::io::Result<()> {
        if self.dirs.is_empty() && self.files.is_empty() && self.links.is_empty() {
            let _ = std::fs::remove_file(&self.file);
            return Ok(());
        }
        if let Some(parent) = self.file.parent().map(Path::to_path_buf) {
            self.create_dir_all(&parent)?;
        }
        let mut text = String::new();
        for d in self.dirs.iter().filter_map(|d| d.to_str()) {
            text.push_str(&format!("D {d}\n"));
        }
        for (p, h) in &self.files {
            if let Some(p) = p.to_str() {
                text.push_str(&format!("F {h} {p}\n"));
            }
        }
        for (l, t) in &self.links {
            if let (Some(l), Some(t)) = (l.to_str(), t.to_str()) {
                text.push_str(&format!("L {l}\t{t}\n"));
            }
        }
        autorename_core::fsx::write_atomic(&self.file, text.as_bytes())
    }

    /// After `remove`: delete the log (unless files we could not remove are
    /// still recorded), then every recorded directory that is empty, deepest
    /// first. Non-empty ones (user files, other apps) stay.
    pub fn prune(mut self) -> std::io::Result<()> {
        let dirs: Vec<_> = std::mem::take(&mut self.dirs).into_iter().collect();
        if self.files.is_empty() && self.links.is_empty() {
            let _ = std::fs::remove_file(&self.file);
        } else {
            self.save()?;
        }
        let mut dirs = dirs;
        dirs.sort_by_key(|d| std::cmp::Reverse(d.components().count()));
        for d in dirs {
            let _ = std::fs::remove_dir(&d);
        }
        Ok(())
    }
}

fn write_entry(e: &FileEntry, log: &mut OwnedLog) -> std::io::Result<()> {
    if let Some(dir) = e.path.parent() {
        log.create_dir_all(dir)?;
    }
    autorename_core::fsx::write_atomic(&e.path, &e.bytes)?;
    if e.owned_by_name {
        log.files.insert(e.path.clone(), sha256_hex(&e.bytes));
    }
    set_mode(&e.path, e.executable)
}

pub fn install_files(entries: &[FileEntry], log: &mut OwnedLog) -> std::io::Result<Vec<Item>> {
    let mut out = Vec::new();
    for e in entries {
        let st = state_of(e, log);
        let it = match st {
            State::Installed => {
                // Mode may have been changed by hand (Dolphin needs +x).
                set_mode(&e.path, e.executable)?;
                // Exactly the bytes we write: ours (re-adopts icons whose
                // ownership record was lost, e.g. by an aborted install).
                if e.owned_by_name && !log.owns_file(&e.path, &e.bytes) {
                    log.files.insert(e.path.clone(), sha256_hex(&e.bytes));
                    log.save()?;
                }
                item(e, State::Installed, Some("unchanged"))
            }
            State::Missing | State::Outdated => {
                write_entry(e, log)?;
                // Persist ownership right after each committed write, so a
                // later failure in the same run cannot orphan this file.
                log.save()?;
                item(e, State::Installed, Some("written"))
            }
            State::Foreign | State::Skipped => {
                let mut i = item(e, st, Some("kept"));
                i.note =
                    Some("not created by autorename-pdf (or modified since); left alone".into());
                i
            }
        };
        out.push(it);
    }
    Ok(out)
}

pub fn remove_files(entries: &[FileEntry], log: &mut OwnedLog) -> std::io::Result<Vec<Item>> {
    let mut out = Vec::new();
    for e in entries {
        let st = state_of(e, log);
        let it = if st == State::Missing {
            log.files.remove(&e.path);
            item(e, st, None)
        } else if removable(e, log) {
            std::fs::remove_file(&e.path)?;
            log.files.remove(&e.path);
            item(e, State::Missing, Some("removed"))
        } else {
            // Not ours (or modified since we wrote it): keep, forget it.
            log.files.remove(&e.path);
            let mut i = item(e, State::Foreign, Some("kept"));
            i.note = Some("not created by autorename-pdf (or modified since); left alone".into());
            i
        };
        out.push(it);
    }
    Ok(out)
}

/// The executable the entries should launch: the AppImage file when running
/// from one (`current_exe` is inside the transient mount), else this binary.
pub fn self_exe() -> std::io::Result<PathBuf> {
    if let Some(p) = std::env::var_os("APPIMAGE").map(PathBuf::from)
        && p.is_file()
    {
        return Ok(p);
    }
    let exe = std::env::current_exe()?;
    Ok(strip_verbatim(std::fs::canonicalize(&exe).unwrap_or(exe)))
}

/// Windows `canonicalize` returns `\\?\C:\…` (verbatim) paths; Explorer
/// verbs and `Icon` values need the plain form.
pub fn strip_verbatim(p: PathBuf) -> PathBuf {
    let Some(s) = p.to_str() else {
        return p;
    };
    if let Some(rest) = s.strip_prefix(r"\\?\UNC\") {
        PathBuf::from(format!(r"\\{rest}"))
    } else if let Some(rest) = s.strip_prefix(r"\\?\")
        && rest.as_bytes().get(1) == Some(&b':')
    {
        PathBuf::from(rest)
    } else {
        p
    }
}

/// POSIX shell single-quoting (Thunar/Nemo commands, Nautilus scripts).
pub fn shell_quote(s: &str) -> String {
    let safe = |c: char| c.is_ascii_alphanumeric() || "_-./,:+=@".contains(c);
    if !s.is_empty() && s.chars().all(safe) {
        s.to_string()
    } else {
        format!("'{}'", s.replace('\'', r"'\''"))
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Action {
    Install,
    Remove,
    Status,
}

/// Run `action` for this platform. `exe` overrides the launched executable.
pub fn run(action: Action, exe: Option<&Path>) -> autorename_core::Result<Report> {
    let exe = match exe {
        Some(p) => std::path::absolute(p).map_err(|e| io_err(p, e))?,
        None => self_exe().map_err(|e| io_err(Path::new("current_exe"), e))?,
    };
    platform_run(action, &exe)
}

pub fn io_err(path: &Path, source: std::io::Error) -> autorename_core::Error {
    autorename_core::Error::Io {
        path: path.to_path_buf(),
        source,
    }
}

#[cfg(all(unix, not(target_os = "macos")))]
fn platform_run(action: Action, exe: &Path) -> autorename_core::Result<Report> {
    linux::run(action, exe)
}

#[cfg(target_os = "macos")]
fn platform_run(action: Action, exe: &Path) -> autorename_core::Result<Report> {
    macos::run(action, exe)
}

#[cfg(windows)]
fn platform_run(action: Action, exe: &Path) -> autorename_core::Result<Report> {
    windows::run(action, exe)
}

#[cfg(not(any(unix, windows)))]
fn platform_run(_: Action, _: &Path) -> autorename_core::Result<Report> {
    Err(autorename_core::Error::Usage {
        message: "No desktop integration for this platform".into(),
        hint: None,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn verbatim_prefix_is_stripped() {
        let f = |s: &str| strip_verbatim(PathBuf::from(s)).display().to_string();
        assert_eq!(f(r"\\?\C:\Users\a\x.exe"), r"C:\Users\a\x.exe");
        assert_eq!(f(r"\\?\UNC\srv\share\x.exe"), r"\\srv\share\x.exe");
        assert_eq!(f("/usr/bin/x"), "/usr/bin/x");
    }

    #[test]
    fn shell_quoting() {
        assert_eq!(
            shell_quote("/usr/bin/autorename-pdf"),
            "/usr/bin/autorename-pdf"
        );
        assert_eq!(shell_quote("/opt/My Apps/a"), "'/opt/My Apps/a'");
        assert_eq!(shell_quote("/x/it's"), r"'/x/it'\''s'");
        assert_eq!(shell_quote(""), "''");
    }

    fn entry(dir: &Path, name: &str, body: &str) -> FileEntry {
        FileEntry {
            kind: "test",
            path: dir.join("a/b").join(name),
            bytes: body.as_bytes().to_vec(),
            executable: true,
            owned_by_name: false,
        }
    }

    #[test]
    fn install_is_idempotent_and_remove_leaves_nothing() {
        let t = tempfile::tempdir().unwrap();
        // A pre-existing empty user directory must survive `remove`.
        std::fs::create_dir(t.path().join("keep")).unwrap();
        let log_file = t.path().join("state/dirs.txt");
        let e = entry(t.path(), "x.desktop", &format!("{MARKER}=1\nA=1\n"));
        let mut log = OwnedLog::load(log_file.clone());
        let i = install_files(std::slice::from_ref(&e), &mut log).unwrap();
        assert_eq!(i[0].action, Some("written"));
        log.save().unwrap();
        let mut log = OwnedLog::load(log_file.clone());
        let i = install_files(std::slice::from_ref(&e), &mut log).unwrap();
        assert_eq!(i[0].action, Some("unchanged"));
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let m = std::fs::metadata(&e.path).unwrap().permissions().mode();
            assert_eq!(m & 0o777, 0o755);
        }
        // Outdated owned entry is rewritten.
        let e2 = entry(t.path(), "x.desktop", &format!("{MARKER}=1\nA=2\n"));
        assert_eq!(
            status_files(std::slice::from_ref(&e2), &log)[0].state,
            State::Outdated
        );
        log.save().unwrap();
        let mut log = OwnedLog::load(log_file);
        let i = remove_files(std::slice::from_ref(&e2), &mut log).unwrap();
        assert_eq!(i[0].action, Some("removed"));
        log.prune().unwrap();
        let left: Vec<_> = std::fs::read_dir(t.path())
            .unwrap()
            .map(|e| e.unwrap().file_name())
            .collect();
        assert_eq!(left, vec![std::ffi::OsString::from("keep")]);
    }

    #[test]
    fn foreign_files_are_never_touched() {
        let t = tempfile::tempdir().unwrap();
        let e = entry(t.path(), "x.desktop", &format!("{MARKER}=1\n"));
        std::fs::create_dir_all(e.path.parent().unwrap()).unwrap();
        std::fs::write(&e.path, "user file").unwrap();
        let mut log = OwnedLog::load(t.path().join("log"));
        let i = install_files(std::slice::from_ref(&e), &mut log).unwrap();
        assert_eq!((i[0].state, i[0].action), (State::Foreign, Some("kept")));
        let i = remove_files(std::slice::from_ref(&e), &mut log).unwrap();
        assert_eq!(i[0].action, Some("kept"));
        assert_eq!(std::fs::read_to_string(&e.path).unwrap(), "user file");
    }

    fn icon(dir: &Path, bytes: &[u8]) -> FileEntry {
        FileEntry {
            kind: "icon",
            path: dir.join("hicolor/16x16/apps/autorename-pdf.png"),
            bytes: bytes.to_vec(),
            executable: false,
            owned_by_name: true,
        }
    }

    /// Review finding: an icon name alone must not confer ownership.
    #[test]
    fn foreign_icon_is_preserved_on_install_and_remove() {
        let t = tempfile::tempdir().unwrap();
        let e = icon(t.path(), b"ours");
        std::fs::create_dir_all(e.path.parent().unwrap()).unwrap();
        std::fs::write(&e.path, b"foreign icon").unwrap();
        let mut log = OwnedLog::load(t.path().join("log"));
        let i = install_files(std::slice::from_ref(&e), &mut log).unwrap();
        assert_eq!((i[0].state, i[0].action), (State::Foreign, Some("kept")));
        let i = remove_files(std::slice::from_ref(&e), &mut log).unwrap();
        assert_eq!(i[0].action, Some("kept"));
        assert_eq!(std::fs::read(&e.path).unwrap(), b"foreign icon");
    }

    #[test]
    fn our_icon_is_updated_and_removed_but_a_modified_one_is_kept() {
        let t = tempfile::tempdir().unwrap();
        let lf = t.path().join("log");
        let v1 = icon(t.path(), b"v1");
        let mut log = OwnedLog::load(lf.clone());
        install_files(std::slice::from_ref(&v1), &mut log).unwrap();
        log.save().unwrap();
        // Newer version replaces our own older icon.
        let v2 = icon(t.path(), b"v2");
        let mut log = OwnedLog::load(lf.clone());
        assert_eq!(
            status_files(std::slice::from_ref(&v2), &log)[0].state,
            State::Outdated
        );
        let i = install_files(std::slice::from_ref(&v2), &mut log).unwrap();
        assert_eq!(i[0].action, Some("written"));
        log.save().unwrap();
        // The user edits it afterwards: no longer ours.
        std::fs::write(&v2.path, b"user edit").unwrap();
        let mut log = OwnedLog::load(lf.clone());
        let i = remove_files(std::slice::from_ref(&v2), &mut log).unwrap();
        assert_eq!(i[0].action, Some("kept"));
        assert_eq!(std::fs::read(&v2.path).unwrap(), b"user edit");
        // Unmodified: removed.
        std::fs::write(&v2.path, b"v2").unwrap();
        let mut log = OwnedLog::load(lf.clone());
        log.files.insert(v2.path.clone(), sha256_hex(b"v2"));
        let i = remove_files(std::slice::from_ref(&v2), &mut log).unwrap();
        assert_eq!(i[0].action, Some("removed"));
        assert!(!v2.path.exists());
    }
}
